/**
 * Creates a demo household for local development: one adult user, four people with a 20-meal plan.
 * Meals are generated by the app itself the first time you open it.
 *
 *   SUPABASE_URL=http://127.0.0.1:54321 SUPABASE_ANON_KEY=... SUPABASE_SERVICE_ROLE_KEY=... pnpm seed:demo
 *
 * The service-role key is read from the shell only. It must never be put in .env.local or the app.
 */
import { createClient } from '@supabase/supabase-js'
import type { Database } from '../src/data/database.types'
import { todayInBolivia } from '../src/domain/bolivia-time'
import { addMonths, monthStart } from '../src/domain/plain-date'

const url = process.env.SUPABASE_URL ?? 'http://127.0.0.1:54321'
const anonKey = process.env.SUPABASE_ANON_KEY
const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY
if (!anonKey || !serviceKey) {
  throw new Error('Set SUPABASE_ANON_KEY and SUPABASE_SERVICE_ROLE_KEY in your shell.')
}

const email = 'demo@nutrilara.local'
const password = 'demo-password-123'

const admin = createClient<Database>(url, serviceKey, { auth: { persistSession: false } })
const created = await admin.auth.admin.createUser({ email, password, email_confirm: true })
if (created.error && !/already/i.test(created.error.message)) throw created.error

const app = createClient<Database>(url, anonKey, { auth: { persistSession: false } })
const signedIn = await app.auth.signInWithPassword({ email, password })
if (signedIn.error) throw signedIn.error

const household = await app.rpc('create_household', { p_name: 'Casa Demo', p_display_name: 'Demo' })
if (household.error && !household.error.message.includes('E_HOUSEHOLD_EXISTS')) throw household.error

const { data: membership } = await app.from('household_members').select('household_id').maybeSingle()
if (!membership) throw new Error('The demo user does not belong to a household.')

// Start two months back so the history screens have something to show.
const start = addMonths(monthStart(todayInBolivia()), -2)
for (const first_name of ['Gonzalo', 'Esposa', 'Hijo', 'Hija']) {
  const existing = await app.from('people').select('id').eq('first_name', first_name).maybeSingle()
  if (existing.data) continue
  const person = await app
    .from('people')
    .insert({ household_id: membership.household_id, first_name, plan_start_date: start })
    .select('id')
    .single()
  if (person.error) throw person.error
  const term = await app.from('plan_terms').insert({ person_id: person.data.id, effective_from: start })
  if (term.error) throw term.error
}

console.log(`Demo ready. Sign in with ${email} / ${password}`)
